class Solution {
    static long beaconSignal(long x1, long y1, long x2, long y2, long xl, long yl, long R) {
        long xLo = Math.max(x1, xl - R);
        long xHi = Math.min(x2, xl + R);
        long total = 0;
        long R2 = R * R;
        for (long x = xLo; x <= xHi; x++) {
            long dx2 = (x - xl) * (x - xl);
            if (dx2 > R2) continue;
            long h = (long) Math.sqrt((double) (R2 - dx2));
            while ((h + 1) * (h + 1) <= R2 - dx2) h++;
            while (h * h > R2 - dx2) h--;
            long yLo = Math.max(y1, yl - h);
            long yHi = Math.min(y2, yl + h);
            if (yLo <= yHi) total += yHi - yLo + 1;
        }
        return total;
    }
}

