using namespace std;

long long beaconSignal(long long x1, long long y1, long long x2, long long y2, long long xl,
                       long long yl, long long R) {
    long long xLo = max(x1, xl - R);
    long long xHi = min(x2, xl + R);
    long long total = 0;
    long long R2 = R * R;
    for (long long x = xLo; x <= xHi; ++x) {
        long long dx2 = (x - xl) * (x - xl);
        if (dx2 > R2) continue;
        long long h = (long long)sqrtl((long double)(R2 - dx2));
        while ((h + 1) * (h + 1) <= R2 - dx2) ++h;
        while (h * h > R2 - dx2) --h;
        long long yLo = max(y1, yl - h);
        long long yHi = min(y2, yl + h);
        if (yLo <= yHi) total += yHi - yLo + 1;
    }
    return total;
}
